code_examples.vulnerable:
const mysql = require("mysql");

// 커넥션 초기화 옵션은 생략함
const connection = mysql.createConnection(...);

router.get("/vuln/email", (req, res) => {
  const con = connection;
  const userInput = req.query.id;
  // 사용자로부터 입력받은 값을 검증 없이 그대로 쿼리에 사용
  const query = `SELECT email FROM user WHERE user_id = ${userInput}`;
  con.query(query,
    (err, result) => {
      if (err) console.log(err);
      return res.send(result);
    }
  );
});

code_examples.safe:
const mysql = require("mysql");
...
router.get("/patched/email", (req, res) => {
  const con = connection;
  const userInput = req.query.id;
  const query = 'SELECT email FROM user WHERE user_id = ?';
  // 쿼리 함수에 사용자 입력값을 매개변수 형태로 전달 → escape 처리한 것과 동일한 효과
  con.query(query, userInput,
    (err, result) => {
      if (err) console.log(err);
      return res.send(result);
    }
  );
});

code_examples.vulnerable:
// ORM의 인자화 기능을 쓰지 않고 사용자 입력값을 원시 쿼리에 직접 결합
const userInput = req.query.id;
const result = await sequelize.query(
  `SELECT email FROM user WHERE user_id = ${userInput}`
);

code_examples.safe:
// replacements(또는 bind)로 외부 입력값을 바인딩 변수로 전달
const userInput = req.query.id;
const result = await sequelize.query(
  'SELECT email FROM user WHERE user_id = ?',
  { replacements: [userInput], type: sequelize.QueryTypes.SELECT }
);
